document.addEventListener("DOMContentLoaded",function(){const t=document.querySelectorAll(".lessons__tab");t.forEach(function(e){e.addEventListener("click",function(){t.forEach(function(t){t.classList.remove("lessons__tab--active")}),e.classList.add("lessons__tab--active")})});const e=document.querySelectorAll(".lesson-item__progress-fill");e.forEach(function(t){const e=t.style.width;t.style.width="0%",setTimeout(function(){t.style.width=e},200)})});